package io.github.turbopro.ism.bootstrap;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;
import org.springframework.http.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class SupportRequestIT extends SiteProjectSupport {
    JsonNode ok(ResponseEntity<JsonNode> r){assertThat(r.getStatusCode()).as("%s",r.getBody()).isEqualTo(HttpStatus.OK);return r.getBody().path("data");}
    Map<String,Object> proposal(){return Map.of("ticketNo","HELP-TEST","reason","排查基础档案展示问题","profileCode","SUPPLIER_BASIC_READ_V1","durationMinutes",30);}
    JsonNode create(Fixture f,String t){return ok(request("POST","/api/console/tenants/"+f.tenant()+"/support-requests",t,UUID.randomUUID().toString(),proposal()));}
    ResponseEntity<JsonNode> change(String id,String t,String action,int v,String key){return request("POST","/api/console/support-requests/"+id+"/"+action,t,key,Map.of("version",v,"comment","测试"+action));}
    @Test void independentReviewThenOwnerCancellationHasDurableEventsAndNoBusinessAccess(){var f=fixture();String owner=login(false),reviewer=login(true);var c=create(f,owner);String id=c.path("id").asText();assertThat(request("GET","/api/console/support-requests/"+id,reviewer,null,null).getStatusCode()).isEqualTo(HttpStatus.NOT_FOUND);var sub=ok(change(id,owner,"submit",0,"submit-"+id));assertThat(sub.path("status").asText()).isEqualTo("SUBMITTED");var approved=ok(change(id,reviewer,"approve",1,"approve-"+id));assertThat(approved.path("status").asText()).isEqualTo("PLATFORM_APPROVED");assertThat(approved.path("events").size()).isEqualTo(3);assertThat(approved.has("accessToken")).isFalse();assertThat(request("GET","/api/suppliers",owner,null,null).getStatusCode().value()).isIn(401,403);var cancelled=ok(change(id,owner,"cancel",2,"cancel-"+id));assertThat(cancelled.path("status").asText()).isEqualTo("CANCELLED");assertThat(cancelled.path("events").findValuesAsText("requestVersion")).containsExactly("0","1","2","3");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM plt_support_approval WHERE request_id=?",Integer.class,id)).isOne();}
    @Test void ownerVisibilityRealPaginationAndReadonlyProfileCannotBeExpanded(){var f=fixture();String owner=login(false),reviewer=login(true);var c=create(f,owner);String id=c.path("id").asText();assertThat(c.path("profile").path("fields").toString()).isEqualTo("[\"id\",\"code\",\"name\",\"type\",\"status\"]");assertThat(request("GET","/api/console/support-requests?review=true",owner,null,null).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(ok(request("GET","/api/console/support-requests?size=1",owner,null,null)).path("items").size()).isOne();assertThat(ok(request("GET","/api/console/support-requests",reviewer,null,null)).path("items").findValuesAsText("id")).doesNotContain(id);var invalid=new HashMap<>(proposal());invalid.put("profileCode","TENANT_ADMIN_WRITE");assertThat(request("POST","/api/console/tenants/"+f.tenant()+"/support-requests",owner,"bad-profile-"+id,invalid).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);assertThat(request("GET","/api/console/support-requests?page=2147483647",owner,null,null).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);}
    @Test void selfReviewAndForeignOwnerWritesAreDeniedAndRejectIsFinal(){var f=fixture();String admin=login(true),support=login(false);String id=create(f,admin).path("id").asText();ok(change(id,admin,"submit",0,"self-sub-"+id));assertThat(change(id,admin,"approve",1,"self-app-"+id).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(change(id,support,"cancel",1,"other-cancel-"+id).getStatusCode()).isEqualTo(HttpStatus.NOT_FOUND);String other=create(f,support).path("id").asText();ok(change(other,support,"submit",0,"reject-sub-"+other));assertThat(ok(change(other,admin,"reject",1,"reject-"+other)).path("status").asText()).isEqualTo("REJECTED");assertThat(change(other,admin,"approve",2,"reject-again-"+other).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);}
    @Test void expiredAndUnavailableTenantCannotBecomeApproved(){var f=fixture();String owner=login(false),reviewer=login(true);String id=create(f,owner).path("id").asText();ok(change(id,owner,"submit",0,"expiry-sub-"+id));jdbc.update("UPDATE plt_support_request SET requested_expire_at=DATE_SUB(UTC_TIMESTAMP(3),INTERVAL 1 SECOND) WHERE id=?",id);assertThat(change(id,reviewer,"approve",1,"expired-"+id).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);assertThat(ok(request("GET","/api/console/support-requests/"+id,owner,null,null)).path("status").asText()).isEqualTo("EXPIRED");ok(change(id,owner,"cancel",1,"expired-cancel-"+id));String pending=create(f,owner).path("id").asText();ok(change(pending,owner,"submit",0,"pause-sub-"+pending));jdbc.update("UPDATE plt_tenant SET status='SUSPENDED' WHERE id=?",f.tenant());assertThat(change(pending,reviewer,"approve",1,"paused-"+pending).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);ok(change(pending,reviewer,"reject",1,"paused-reject-"+pending));}
    @Test void replayAndAuditFailureKeepOneDecisionAndUnchangedVersion()throws Exception{var f=fixture();String owner=login(false),reviewer=login(true);String id=create(f,owner).path("id").asText();var first=ok(change(id,owner,"submit",0,"replay-sub-"+id));assertThat(ok(change(id,owner,"submit",0,"replay-sub-"+id))).isEqualTo(first);trigger("CREATE TRIGGER sr_audit_fail BEFORE INSERT ON sys_audit_event FOR EACH ROW BEGIN IF NEW.action='SUPPORT_REQUEST_APPROVE' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test support audit failure'; END IF; END");try{assertThat(change(id,reviewer,"approve",1,"audit-"+id).getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);}finally{trigger("DROP TRIGGER sr_audit_fail");}assertThat(jdbc.queryForObject("SELECT status FROM plt_support_request WHERE id=?",String.class,id)).isEqualTo("SUBMITTED");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM plt_support_approval WHERE request_id=?",Integer.class,id)).isZero();ok(change(id,reviewer,"approve",1,"audit-"+id));assertThat(change(id,reviewer,"reject",1,"audit-"+id).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);}
    @Test void viewRevocationBlocksReviewReceiptReplay(){var f=fixture();String owner=login(false),reviewer=login(true);String id=create(f,owner).path("id").asText();ok(change(id,owner,"submit",0,"revoke-sub-"+id));ok(change(id,reviewer,"approve",1,"revoke-app-"+id));jdbc.update("DELETE FROM plt_role_permission WHERE role_id=1001 AND permission_id=1124");try{assertThat(change(id,reviewer,"approve",1,"revoke-app-"+id).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);}finally{jdbc.update("INSERT INTO plt_role_permission(role_id,permission_id) VALUES(1001,1124)");}}
    @Test void competingDecisionsHaveOneWinner()throws Exception{var f=fixture();String owner=login(false),reviewer=login(true);String id=create(f,owner).path("id").asText();ok(change(id,owner,"submit",0,"race-sub-"+id));var gate=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var one=pool.submit(()->{gate.await();return change(id,reviewer,"approve",1,"race-approve-"+id).getStatusCode().value();});var two=pool.submit(()->{gate.await();return change(id,reviewer,"reject",1,"race-reject-"+id).getStatusCode().value();});gate.countDown();assertThat(List.of(one.get(30,TimeUnit.SECONDS),two.get(30,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);}finally{pool.shutdownNow();}assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM plt_support_approval WHERE request_id=?",Integer.class,id)).isOne();}
}
